contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint sendValue, bytes memory data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= sendValue, "not enough balance");

        uint beforeBalance = address(c).balance;
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool success;
        c.sendMoney(address(this), sendValue, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            success = false;
        } else {
            success = true;
        }

        uint afterBalance = address(c).balance;
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(!success || afterCount == beforeCount);
    }
}

